import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

/** Create an independent, strict UTF-8 decoder for the bounded stream protocol. */
export function createDecoder() {
  const utf8 = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true});
  let poisoned = false;
  let finished = false;
  let terminated = false;
  let sawStart = false;
  let pending = '';
  let data = [];
  let event;

  const fail = (message) => { throw new Error(message); };
  const reset = () => { data = []; event = undefined; };

  function consumeLine(line, frames) {
    if (terminated) {
      if (line !== '') fail('nonblank line after termination');
      return;
    }
    if (line === '') {
      if (data.length) {
        const value = data.join('\n');
        const name = event === undefined || event === '' ? 'message' : event;
        reset();
        if (value === '[DONE]') terminated = true;
        else frames.push({event: name, data: value});
      } else {
        reset();
      }
      return;
    }
    if (line.startsWith(':')) return;
    const colon = line.indexOf(':');
    const field = colon < 0 ? line : line.slice(0, colon);
    let value = colon < 0 ? '' : line.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (field === 'data') data.push(value);
    else if (field === 'event') event = value;
  }

  function acceptText(text, frames) {
    if (!sawStart) {
      sawStart = true;
      if (text.startsWith('\uFEFF')) text = text.slice(1);
    }
    pending += text;
    let lf;
    while ((lf = pending.indexOf('\n')) !== -1) {
      const contentEnd = lf > 0 && pending[lf - 1] === '\r' ? lf - 1 : lf;
      consumeLine(pending.slice(0, contentEnd), frames);
      pending = pending.slice(lf + 1);
    }
  }

  function guarded(work) {
    if (poisoned) fail('decoder is poisoned');
    try { return work(); }
    catch (error) { poisoned = true; throw error instanceof Error ? error : new Error(String(error)); }
  }

  return {
    push(chunk) {
      return guarded(() => {
        if (finished) fail('decoder is finished');
        if (!(chunk instanceof Uint8Array)) fail('chunk must be a Uint8Array');
        const frames = [];
        acceptText(utf8.decode(chunk, {stream: true}), frames);
        return frames;
      });
    },
    finish() {
      return guarded(() => {
        if (finished) fail('decoder is finished');
        const frames = [];
        acceptText(utf8.decode(), frames);
        if (pending !== '') fail('unterminated line');
        if (!terminated) fail('missing termination marker');
        if (data.length || event !== undefined) fail('pending frame');
        finished = true;
        return frames;
      });
    },
  };
}

function decodeInputFile(file) {
  const bytes = fs.readFileSync(file);
  return new TextDecoder('utf-8', {fatal: true}).decode(bytes);
}

function decodeCanonicalBase64(value) {
  if (typeof value !== 'string' || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value)) {
    throw new Error('invalid base64 chunk');
  }
  const bytes = Buffer.from(value, 'base64');
  if (bytes.toString('base64') !== value) throw new Error('noncanonical base64 chunk');
  return bytes;
}

function runCli() {
  if (process.argv.length !== 3) throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
  const input = JSON.parse(decodeInputFile(process.argv[2]));
  if (input === null || Array.isArray(input) || typeof input !== 'object' || !Array.isArray(input.chunks)) {
    throw new Error('input must be an object with a chunks array');
  }
  const decoder = createDecoder();
  const frames = [];
  for (const encoded of input.chunks) frames.push(...decoder.push(decodeCanonicalBase64(encoded)));
  frames.push(...decoder.finish());
  process.stdout.write(JSON.stringify({frames}) + '\n');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { runCli(); }
  catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

