const source = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
const bytes = (text) => Buffer.from(text, 'utf8');

function decode(parts) {
  const d = createDecoder();
  const frames = [];
  for (const part of parts) frames.push(...d.push(part));
  assert.deepEqual(d.finish(), []);
  return frames;
}

test('byte and all two-way chunk splits preserve BOM, UTF-8, CRLF and frames', () => {
  const input = bytes('\uFEFFevent: snow\r\ndata: 雪😀\r\ndata: second\r\n\r\ndata: [DONE]\r\n\r\n');
  const expected = [{event: 'snow', data: '雪😀\nsecond'}];
  const original = Buffer.from(input);
  assert.deepEqual(decode([input]), expected);
  assert.deepEqual(input, original);
  for (let i = 0; i <= input.length; i++) assert.deepEqual(decode([input.subarray(0, i), input.subarray(i)]), expected);
  assert.deepEqual(decode([...input].map((b) => Uint8Array.of(b))), expected);
});

test('preserves exact fields and resets event state on empty frames and dispatches', () => {
  const d = createDecoder();
  const input = 'event: old\n\nevent: custom\ndata:  leading \rhere\ndata:\ndata: \n\n' +
    'event: stale\ndata: value\n\ndata: next\ndata: \uFEFFlater\n\n' +
    'data: [DONE]\n\n\n';
  assert.deepEqual(d.push(bytes(input)), [
    {event: 'custom', data: ' leading \rhere\n\n'},
    {event: 'stale', data: 'value'},
    {event: 'message', data: 'next\n\uFEFFlater'},
  ]);
  assert.deepEqual(d.finish(), []);
});

test('invalid inputs, incomplete lines, and protocol errors poison only their decoder', () => {
  for (const trigger of [
    (d) => d.push('nope'),
    (d) => { d.push(Uint8Array.of(0xc3)); d.finish(); },
    (d) => d.push(Uint8Array.of(0xc3, 0x28)),
    (d) => d.finish(),
    (d) => { d.push(bytes('data: [DONE]\n\n: bad\n')); },
    (d) => { d.push(bytes('data: x')); d.finish(); },
  ]) {
    const d = createDecoder();
    assert.throws(() => trigger(d), Error);
    assert.throws(() => d.push(bytes('data: [DONE]\n\n')), Error);
    assert.throws(() => d.finish(), Error);
  }
  assert.deepEqual(decode([bytes('data: independent\n\ndata: [DONE]\n\n')]), [{event: 'message', data: 'independent'}]);
});

test('DONE is suppressed and rejects every nonblank post-termination line', () => {
  for (const line of ['data: [DONE]\n\ndata: again\n', 'data: [DONE]\n\n: c\n', 'data: [DONE]\n\nx: y\n', 'data: [DONE]\n\n\uFEFF\n']) {
    const d = createDecoder();
    assert.throws(() => d.push(bytes(line)), Error);
  }
  const d = createDecoder();
  assert.deepEqual(d.push(bytes('data: [DONE]\n\n\n\r\n')), []);
  assert.deepEqual(d.finish(), []);
});

test('CLI is import-safe and has exact success and failure channels', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  try {
    const good = path.join(dir, 'good.json');
    fs.writeFileSync(good, JSON.stringify({chunks: [bytes('data: ok\n\ndata: [DONE]\n\n').toString('base64')], ignored: true}));
