test('protocol edge cases retain exact field, termination, and lifecycle semantics', () => {
  const fields = createDecoder();
  assert.deepEqual(fields.push(bytes('Event: ignored\nDATA: ignored\n: comment\nevent: named\nevent:\ndata: value\n\ndata: [DONE]\n\n')), [{event: 'message', data: 'value'}]);
  assert.deepEqual(fields.finish(), []);

  const nearDone = createDecoder();
  assert.deepEqual(nearDone.push(bytes('data: [DONE] \n\ndata: [done]\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: '[DONE] '}, {event: 'message', data: '[done]'},
  ]);
  assert.deepEqual(nearDone.finish(), []);
  const second = createDecoder();
  assert.throws(() => second.push(bytes('data: [DONE]\n\ndata: [DONE]\n\n')), Error);

  const pending = createDecoder();
  assert.deepEqual(pending.push(bytes('event: retained\ndata: complete\n')), []);
  assert.throws(() => pending.finish(), Error);
  for (const value of [null, {}, [], new DataView(new ArrayBuffer(1)), 1]) {
    const d = createDecoder();
    assert.throws(() => d.push(value), Error);
  }

  const utf8AfterDone = createDecoder();
  assert.deepEqual(utf8AfterDone.push(bytes('data: [DONE]\n\n')), []);
  assert.deepEqual(utf8AfterDone.push(Uint8Array.of(0xc3)), []);
  assert.throws(() => utf8AfterDone.finish(), Error);

  const preserved = createDecoder();
  const returned = preserved.push(bytes('data: before\n\n'));
  assert.throws(() => preserved.push(Uint8Array.of(0xc3, 0x28)), Error);
  assert.deepEqual(returned, [{event: 'message', data: 'before'}]);

  const closed = createDecoder();
  closed.push(bytes('data: [DONE]\n\n'));
  assert.deepEqual(closed.finish(), []);
  assert.throws(() => closed.finish(), Error);
  assert.throws(() => closed.push(new Uint8Array()), Error);
});

test('CLI handles a large single batch without argument spreading', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-large-'));
  try {
    const file = path.join(dir, 'large.json');
    fs.writeFileSync(file, JSON.stringify({chunks: [bytes('data:\n\n'.repeat(150000) + 'data: [DONE]\n\n').toString('base64')]));
    const result = spawnSync(process.execPath, [source, file], {encoding: 'utf8', maxBuffer: 32 * 1024 * 1024});
    assert.equal(result.status, 0); assert.equal(result.stderr, '');
    const output = JSON.parse(result.stdout);
    assert.equal(output.frames.length, 150000);
    assert.ok(output.frames.every((frame) => frame.event === 'message' && frame.data === ''));
  } finally { fs.rmSync(dir, {recursive: true, force: true}); }
});

test('CLI rejects argument, file, JSON, chunk-type, and padding failures while accepting empty base64', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-cli-'));
  const run = (args) => spawnSync(process.execPath, [source, ...args], {encoding: 'utf8'});
  const rejected = (args) => {
