import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createDecoder} from '../stream-framer.js';

const source = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
const bytes = (text) => Buffer.from(text, 'utf8');

function decode(parts) {
  const d = createDecoder();
  const frames = [];
  for (const part of parts) frames.push(...d.push(part));
  assert.deepEqual(d.finish(), []);
  return frames;
}

test('byte and all two-way chunk splits preserve BOM, UTF-8, CRLF and frames', () => {
  const input = bytes('\uFEFFevent: snow\r\ndata: 雪😀\r\ndata: second\r\n\r\ndata: [DONE]\r\n\r\n');
  const expected = [{event: 'snow', data: '雪😀\nsecond'}];
  const original = Buffer.from(input);
  assert.deepEqual(decode([input]), expected);
  assert.deepEqual(input, original);
  for (let i = 0; i <= input.length; i++) assert.deepEqual(decode([input.subarray(0, i), input.subarray(i)]), expected);
  assert.deepEqual(decode([...input].map((b) => Uint8Array.of(b))), expected);
});

test('preserves exact fields and resets event state on empty frames and dispatches', () => {
  const d = createDecoder();
  const input = 'event: old\n\nevent: custom\ndata:  leading \rhere\ndata:\ndata: \n\n' +
    'event: stale\ndata: value\n\ndata: next\ndata: \uFEFFlater\n\n' +
    'data: [DONE]\n\n\n';
  assert.deepEqual(d.push(bytes(input)), [
    {event: 'custom', data: ' leading \rhere\n\n'},
    {event: 'stale', data: 'value'},
    {event: 'message', data: 'next\n\uFEFFlater'},
  ]);
  assert.deepEqual(d.finish(), []);
});

test('invalid inputs, incomplete lines, and protocol errors poison only their decoder', () => {
  for (const trigger of [
    (d) => d.push('nope'),
    (d) => { d.push(Uint8Array.of(0xc3)); d.finish(); },
    (d) => d.push(Uint8Array.of(0xc3, 0x28)),
    (d) => d.finish(),
    (d) => { d.push(bytes('data: [DONE]\n\n: bad\n')); },
    (d) => { d.push(bytes('data: x')); d.finish(); },
  ]) {
    const d = createDecoder();
    assert.throws(() => trigger(d), Error);
    assert.throws(() => d.push(bytes('data: [DONE]\n\n')), Error);
    assert.throws(() => d.finish(), Error);
  }
  assert.deepEqual(decode([bytes('data: independent\n\ndata: [DONE]\n\n')]), [{event: 'message', data: 'independent'}]);
});

test('DONE is suppressed and rejects every nonblank post-termination line', () => {
  for (const line of ['data: [DONE]\n\ndata: again\n', 'data: [DONE]\n\n: c\n', 'data: [DONE]\n\nx: y\n', 'data: [DONE]\n\n\uFEFF\n']) {
    const d = createDecoder();
    assert.throws(() => d.push(bytes(line)), Error);
  }
  const d = createDecoder();
  assert.deepEqual(d.push(bytes('data: [DONE]\n\n\n\r\n')), []);
  assert.deepEqual(d.finish(), []);
});

test('CLI is import-safe and has exact success and failure channels', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  try {
    const good = path.join(dir, 'good.json');
    fs.writeFileSync(good, JSON.stringify({chunks: [bytes('data: ok\n\ndata: [DONE]\n\n').toString('base64')], ignored: true}));
    const success = spawnSync(process.execPath, [source, good], {encoding: 'utf8'});
    assert.equal(success.status, 0); assert.equal(success.stderr, '');
    assert.equal(success.stdout, '{"frames":[{"event":"message","data":"ok"}]}\n');
    for (const [index, value] of [null, [], {}, {chunks: 'x'}, {chunks: ['YQ']}, {chunks: ['YR==']}, {chunks: ['Y Q==']}, {chunks: ['__==']}, {chunks: [bytes('data: x\n').toString('base64')]}].entries()) {
      const file = path.join(dir, `bad-${index}.json`);
      fs.writeFileSync(file, JSON.stringify(value));
      const result = spawnSync(process.execPath, [source, file], {encoding: 'utf8'});
      assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
    }
    const args = spawnSync(process.execPath, [source], {encoding: 'utf8'});
    assert.equal(args.status, 2); assert.equal(args.stdout, ''); assert.notEqual(args.stderr, '');
    const imported = spawnSync(process.execPath, ['-e', `import(${JSON.stringify(new URL('../stream-framer.js', import.meta.url).href)})`], {encoding: 'utf8'});
    assert.equal(imported.status, 0); assert.equal(imported.stdout, ''); assert.equal(imported.stderr, '');
  } finally { fs.rmSync(dir, {recursive: true, force: true}); }
});

test('protocol edge cases retain exact field, termination, and lifecycle semantics', () => {
  const fields = createDecoder();
  assert.deepEqual(fields.push(bytes('Event: ignored\nDATA: ignored\n: comment\nevent: named\nevent:\ndata: value\n\ndata: [DONE]\n\n')), [{event: 'message', data: 'value'}]);
  assert.deepEqual(fields.finish(), []);

  const nearDone = createDecoder();
  assert.deepEqual(nearDone.push(bytes('data: [DONE] \n\ndata: [done]\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: '[DONE] '}, {event: 'message', data: '[done]'},
  ]);
  assert.deepEqual(nearDone.finish(), []);
  const second = createDecoder();
  assert.throws(() => second.push(bytes('data: [DONE]\n\ndata: [DONE]\n\n')), Error);

  const pending = createDecoder();
  assert.deepEqual(pending.push(bytes('event: retained\ndata: complete\n')), []);
  assert.throws(() => pending.finish(), Error);
  for (const value of [null, {}, [], new DataView(new ArrayBuffer(1)), 1]) {
    const d = createDecoder();
    assert.throws(() => d.push(value), Error);
  }

  const utf8AfterDone = createDecoder();
  assert.deepEqual(utf8AfterDone.push(bytes('data: [DONE]\n\n')), []);
  assert.deepEqual(utf8AfterDone.push(Uint8Array.of(0xc3)), []);
  assert.throws(() => utf8AfterDone.finish(), Error);

  const preserved = createDecoder();
  const returned = preserved.push(bytes('data: before\n\n'));
  assert.throws(() => preserved.push(Uint8Array.of(0xc3, 0x28)), Error);
  assert.deepEqual(returned, [{event: 'message', data: 'before'}]);

  const closed = createDecoder();
  closed.push(bytes('data: [DONE]\n\n'));
  assert.deepEqual(closed.finish(), []);
  assert.throws(() => closed.finish(), Error);
