test('CLI handles a large single batch without argument spreading', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-large-'));
  try {
    const file = path.join(dir, 'large.json');
    fs.writeFileSync(file, JSON.stringify({chunks: [bytes('data:\n\n'.repeat(150000) + 'data: [DONE]\n\n').toString('base64')]}));
    const result = spawnSync(process.execPath, [source, file], {encoding: 'utf8', maxBuffer: 32 * 1024 * 1024});
    assert.equal(result.status, 0); assert.equal(result.stderr, '');
    const output = JSON.parse(result.stdout);
    assert.equal(output.frames.length, 150000);
    assert.ok(output.frames.every((frame) => frame.event === 'message' && frame.data === ''));
  } finally { fs.rmSync(dir, {recursive: true, force: true}); }
});

test('CLI rejects argument, file, JSON, chunk-type, and padding failures while accepting empty base64', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-cli-'));
  const run = (args) => spawnSync(process.execPath, [source, ...args], {encoding: 'utf8'});
  const rejected = (args) => {
    const result = run(args);
    assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
  };
  try {
    const valid = path.join(dir, 'empty.json');
    fs.writeFileSync(valid, JSON.stringify({chunks: ['', bytes('data: [DONE]\n\n').toString('base64')]}));
    const ok = run([valid]);
    assert.equal(ok.status, 0); assert.equal(ok.stdout, '{"frames":[]}\n'); assert.equal(ok.stderr, '');
    rejected([valid, 'extra']);
    rejected([path.join(dir, 'missing.json')]);
    const malformed = path.join(dir, 'malformed.json'); fs.writeFileSync(malformed, '{'); rejected([malformed]);
    for (const [name, input] of [['nonstring', {chunks: [1]}], ['padding', {chunks: ['YQ=']}], ['badpads', {chunks: ['A===']}]]) {
      const file = path.join(dir, `${name}.json`); fs.writeFileSync(file, JSON.stringify(input)); rejected([file]);
    }
  } finally { fs.rmSync(dir, {recursive: true, force: true}); }
});

